import { useState, useEffect, useCallback } from 'react'
import './App.css'

const BTC_FEED_ID = '0xe62df6c8b4a85fe1a67db44dc12de5db330f7ac66b72dc658afedf0f4a415b43'
const ROUND_DURATION = 60 // 60 seconds for quick rounds
const TOLERANCE = 0.1 // ±0.1% tolerance for winning

function App() {
  const [btcPrice, setBtcPrice] = useState(null)
  const [startPrice, setStartPrice] = useState(null)
  const [prediction, setPrediction] = useState('')
  const [timeLeft, setTimeLeft] = useState(ROUND_DURATION)
  const [gameState, setGameState] = useState('waiting') // waiting, active, finished
  const [score, setScore] = useState(0)
  const [totalRounds, setTotalRounds] = useState(0)
  const [lastResult, setLastResult] = useState(null)

  // Fetch BTC price from Pyth Hermes API
  const fetchBTCPrice = useCallback(async () => {
    try {
      const response = await fetch(
        `https://hermes.pyth.network/v2/updates/price/latest?ids[]=${BTC_FEED_ID}`
      )
      const data = await response.json()

      if (data.parsed && data.parsed[0]) {
        const priceData = data.parsed[0].price
        const price = parseInt(priceData.price) * Math.pow(10, priceData.expo)
        setBtcPrice(price)
        return price
      }
    } catch (error) {
      console.error('Error fetching BTC price:', error)
    }
    return null
  }, [])

  // Start a new round
  const startRound = useCallback(async () => {
    const currentPrice = await fetchBTCPrice()
    if (currentPrice) {
      setStartPrice(currentPrice)
      setGameState('active')
      setTimeLeft(ROUND_DURATION)
      setPrediction('')
      setLastResult(null)
    }
  }, [fetchBTCPrice])

  // Calculate actual volatility percentage
  const calculateVolatility = (startPrice, endPrice) => {
    return Math.abs((endPrice - startPrice) / startPrice) * 100
  }

  // End round and calculate results
  const endRound = useCallback(async () => {
    const endPrice = await fetchBTCPrice()
    if (endPrice && startPrice && prediction !== '') {
      const actualVolatility = calculateVolatility(startPrice, endPrice)
      const predictedVolatility = parseFloat(prediction)
      const difference = Math.abs(actualVolatility - predictedVolatility)

      let points = 0
      if (difference <= TOLERANCE) {
        points = 100
      }

      setScore(prev => prev + points)
      setTotalRounds(prev => prev + 1)
      setLastResult({
        actualVolatility: actualVolatility.toFixed(3),
        predictedVolatility: predictedVolatility.toFixed(3),
        difference: difference.toFixed(3),
        points,
        startPrice: startPrice.toFixed(2),
        endPrice: endPrice.toFixed(2)
      })
    }
    setGameState('finished')
  }, [startPrice, prediction])

  // Timer countdown effect
  useEffect(() => {
    let interval
    if (gameState === 'active' && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            endRound()
            return 0
          }
          return prev - 1
        })
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [gameState, timeLeft, endRound])

  // Fetch price updates every 2 seconds
  useEffect(() => {
    fetchBTCPrice()
    const interval = setInterval(fetchBTCPrice, 2000)
    return () => clearInterval(interval)
  }, [fetchBTCPrice])

  return (
    <div className="app">
      <header>
        <h1>DADA</h1>
        <p>Bitcoin Volatility Prediction Game</p>
      </header>

      <div className="game-container">
        <div className="price-display">
          <h2>Current BTC Price</h2>
          <div className="price">
            {btcPrice ? `$${btcPrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : 'Loading...'}
          </div>
        </div>

        <div className="game-section">
          {gameState === 'waiting' && (
            <div className="waiting-state">
              <p>Predict how much Bitcoin's price will move (as a percentage) in the next {ROUND_DURATION} seconds!</p>
              <p className="rules">Win 100 points if you're within ±{TOLERANCE}% of the actual volatility</p>
              <button onClick={startRound} className="start-button">
                Start New Round
              </button>
            </div>
          )}

          {gameState === 'active' && (
            <div className="active-state">
              <div className="round-info">
                <p>Round started at: <strong>${startPrice?.toFixed(2)}</strong></p>
                <div className="timer">
                  Time left: <span className="countdown">{timeLeft}s</span>
                </div>
              </div>

              <div className="prediction-input">
                <label htmlFor="prediction">Your volatility prediction (%):</label>
                <input
                  id="prediction"
                  type="number"
                  step="0.01"
                  min="0"
                  max="20"
                  value={prediction}
                  onChange={(e) => setPrediction(e.target.value)}
                  placeholder="e.g. 1.25"
                />
                <p className="hint">Enter the percentage you think BTC will move (up or down)</p>
              </div>
            </div>
          )}

          {gameState === 'finished' && lastResult && (
            <div className="results-state">
              <h3>Round Results</h3>
              <div className="results">
                <div className="result-row">
                  <span>Start Price:</span>
                  <span>${lastResult.startPrice}</span>
                </div>
                <div className="result-row">
                  <span>End Price:</span>
                  <span>${lastResult.endPrice}</span>
                </div>
                <div className="result-row">
                  <span>Actual Volatility:</span>
                  <span>{lastResult.actualVolatility}%</span>
                </div>
                <div className="result-row">
                  <span>Your Prediction:</span>
                  <span>{lastResult.predictedVolatility}%</span>
                </div>
                <div className="result-row">
                  <span>Difference:</span>
                  <span>{lastResult.difference}%</span>
                </div>
                <div className="result-row points">
                  <span>Points Earned:</span>
                  <span className={lastResult.points > 0 ? 'winner' : 'loser'}>
                    {lastResult.points}
                  </span>
                </div>
              </div>

              <button onClick={startRound} className="start-button">
                Play Again
              </button>
            </div>
          )}
        </div>

        <div className="score-section">
          <div className="score-display">
            <h3>Score</h3>
            <div className="score">{score}</div>
            <div className="rounds">Rounds: {totalRounds}</div>
            {totalRounds > 0 && (
              <div className="average">
                Avg: {(score / totalRounds).toFixed(1)} pts/round
              </div>
            )}
          </div>
        </div>
      </div>

      <footer>
        <p>Powered by Pyth Network • Live Bitcoin price data</p>
      </footer>
    </div>
  )
}

export default App

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: linear-gradient(135deg, #1e3c72 0%, #2a5298 100%);
  color: white;
  min-height: 100vh;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
}

header {
  text-align: center;
  margin-bottom: 40px;
}

header h1 {
  font-size: 4rem;
  font-weight: bold;
  letter-spacing: 2px;
  background: linear-gradient(45deg, #f39c12, #e74c3c);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 10px;
}

header p {
  font-size: 1.2rem;
  opacity: 0.9;
  font-weight: 300;
}

.game-container {
  max-width: 800px;
  width: 100%;
  display: grid;
  gap: 30px;
  grid-template-columns: 1fr;
}

.price-display {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 30px;
  text-align: center;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.price-display h2 {
  font-size: 1.5rem;
  margin-bottom: 15px;
  opacity: 0.9;
}

.price {
  font-size: 3.5rem;
  font-weight: bold;
  color: #f39c12;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
}

.game-section {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 30px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  min-height: 300px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.waiting-state {
  text-align: center;
}

.waiting-state p {
  font-size: 1.2rem;
  margin-bottom: 15px;
  line-height: 1.6;
}

.rules {
  background: rgba(46, 204, 113, 0.2);
  padding: 15px;
  border-radius: 10px;
  border-left: 4px solid #2ecc71;
  margin: 20px 0;
  font-weight: 500;
}

.start-button {
  background: linear-gradient(45deg, #e74c3c, #c0392b);
  color: white;
  border: none;
  padding: 15px 40px;
  font-size: 1.3rem;
  font-weight: bold;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.start-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(231, 76, 60, 0.3);
}

.active-state {
  text-align: center;
}

.round-info {
  margin-bottom: 30px;
}

.round-info p {
  font-size: 1.2rem;
  margin-bottom: 20px;
}

.timer {
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.countdown {
  background: linear-gradient(45deg, #e74c3c, #c0392b);
  padding: 10px 20px;
  border-radius: 25px;
  font-weight: bold;
  font-size: 2rem;
  display: inline-block;
  min-width: 80px;
  animation: pulse 1s infinite;
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

.prediction-input {
  max-width: 400px;
  margin: 0 auto;
}

.prediction-input label {
  display: block;
  font-size: 1.2rem;
  margin-bottom: 15px;
  font-weight: 500;
}

.prediction-input input {
  width: 100%;
  padding: 15px;
  font-size: 1.5rem;
  text-align: center;
  border: none;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.9);
  color: #2c3e50;
  font-weight: bold;
}

.prediction-input input:focus {
  outline: 3px solid #f39c12;
  transform: scale(1.02);
}

.hint {
  margin-top: 10px;
  font-size: 0.9rem;
  opacity: 0.7;
  font-style: italic;
}

.results-state {
  text-align: center;
}

.results-state h3 {
  font-size: 1.8rem;
  margin-bottom: 25px;
  color: #f39c12;
}

.results {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 15px;
  padding: 25px;
  margin-bottom: 25px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 1.1rem;
}

.result-row:last-child {
  border-bottom: none;
}

.result-row.points {
  font-size: 1.3rem;
  font-weight: bold;
  border-top: 2px solid rgba(255, 255, 255, 0.2);
  padding-top: 20px;
  margin-top: 15px;
}

.winner {
  color: #2ecc71;
  text-shadow: 0 0 10px rgba(46, 204, 113, 0.5);
}

.loser {
  color: #e74c3c;
}

.score-section {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 25px;
  text-align: center;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.score-display h3 {
  font-size: 1.5rem;
  margin-bottom: 15px;
  opacity: 0.9;
}

.score {
  font-size: 3rem;
  font-weight: bold;
  color: #f39c12;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
  margin-bottom: 10px;
}

.rounds, .average {
  font-size: 1rem;
  opacity: 0.8;
  margin: 5px 0;
}

footer {
  margin-top: 40px;
  text-align: center;
  opacity: 0.6;
  font-size: 0.9rem;
}

/* Responsive design */
@media (min-width: 768px) {
  .game-container {
    grid-template-columns: 2fr 1fr;
    grid-template-areas: 
      "price score"
      "game score";
  }

  .price-display {
    grid-area: price;
  }

  .game-section {
    grid-area: game;
  }

  .score-section {
    grid-area: score;
  }
}

@media (max-width: 480px) {
  header h1 {
    font-size: 3rem;
  }

  .price {
    font-size: 2.5rem;
  }

  .app {
    padding: 10px;
  }

  .game-container {
    gap: 20px;
  }

  .price-display, .game-section, .score-section {
    padding: 20px;
  }
}
